from datetime import datetime

from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, log_error, pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError


class ErrorHistory:
    """ Tracks history of errors occurred during test execution. """

    def __init__(self):
        self._errors = []

    def add(self, error_type: str, error_msg: str):
        """
        Adds new error to history.
        :param error_type: category of error which occurred during test execution, similar to exception class name;
                           i.e. 'Unexpected alarm'
        :param error_msg: text description of error which occurred during test execution, similar to exception message;
                          i.e. 'After cell unblock alarm with fault ID 49 is still active'
        """
        log_error(error_msg, to_console=True)
        self._errors.append(Error(error_type=error_type, error_msg=error_msg))

    def add_from_exception(self, exc: Exception):
        """
        Adds new error to history based on data extracted from given exception.
        :param exc: exception which occurred during test execution
        """
        log_error(str(exc), to_console=True)
        self._errors.append(Error(error_type=type(exc).__name__, error_msg=str(exc)))

    @pretty_log
    def check(self):
        """
        Checks whether history contains any errors.
        Logs each error on ERROR log level.
        Clears errors history.
        :raises ResultError: if history contains at least one error
        """
        if self._errors:
            log_info('*** ERRORS HISTORY ***', to_console=True)

            for error in self._errors:
                log_error(str(error))

            self._errors.clear()
            raise ResultError('There were some errors during test execution. '
                              'Refer to above error messages for more details.')

        log_info('There were no errors during test execution')


class Error:
    """ Represents error occurred during test execution. """

    def __init__(self, error_type: str, error_msg: str):
        self._time = datetime.now()
        self._type = error_type
        self._msg = error_msg

    def __str__(self):
        return f'{self._time} {self._type}: {self._msg}'
